using System;
using System.Linq;
using System.Collections.Generic;

namespace AABattle {
 static class SwitchRuntimeTests {
  static void Check(bool ok,string label){if(!ok)throw new Exception("Switch runtime FAIL: "+label);}
  static Fighter Role(Fighter source,string role,string description,string trigger){var p=source.Data;return new Fighter(new Pokemon{id="role-test",name=role+" 보유자",level=p.level,@base=(int[])p.@base.Clone(),iv=(int[])p.iv.Clone(),types=(string[])p.types.Clone(),moves=(string[])p.moves.Clone(),potentials=new[]{new Potential{id="역할",name=role,description=description,triggers=new[]{trigger}}}});}
  static Fighter Tracker(Fighter source){return Role(source,"추적대원",EffectNormalizer.CanonicalSwitchRestriction(),TriggerStructures.FieldLabel);}
  static void WildEntryTest(Database db){var source=new Fighter(db.pokemon.First(p=>p.name=="선데이"));var opponent=new Fighter(db.pokemon.First(p=>p.name=="잭 한마"));var rules=new Rules();var random=Role(source,"야생 포켓몬",EffectNormalizer.CanonicalRank("자신의 임의의 능력",2),TriggerStructures.EntryLabel);var log=new List<string>();EntryTriggers.Enter(random,opponent,rules,()=>0,EntryReason.Lead,log.Add);Check(random.Stages[1]==2&&random.Stages.Skip(2).All(x=>x==0)&&random.Conditions.RoleEntryApplied&&log.Any(x=>x.Contains("『야생 포켓몬』")),"wild random stat rises on entry");int before=random.Stages[1];EntryTriggers.Enter(random,opponent,rules,()=>.99,EntryReason.Lead,log.Add);Check(random.Stages[1]==before,"wild entry effect applies once per entry state");var explorer=Role(source,"탐사대원",EffectNormalizer.CanonicalRank("자신의 임의의 능력",1),TriggerStructures.EntryLabel);EntryTriggers.Enter(explorer,opponent,rules,()=>0,EntryReason.NormalSwitch,log.Add);Check(explorer.Stages[1]==1&&explorer.Stages.Skip(2).All(x=>x==0),"explorer random stat rises on entry");var boss=Role(source,"야생의 두목",EffectNormalizer.CanonicalRank("자신의 전능력치",2),TriggerStructures.EntryLabel);EntryTriggers.Enter(boss,opponent,rules,()=>0,EntryReason.NormalSwitch,log.Add);Check(Enumerable.Range(1,5).All(i=>boss.Stages[i]==2),"wild boss raises all stats on entry");var forced=Role(source,"야생의 두목",EffectNormalizer.CanonicalRank("자신의 전능력치",2),TriggerStructures.EntryLabel);EntryTriggers.Enter(forced,opponent,rules,()=>0,EntryReason.Forced,log.Add);Check(Enumerable.Range(1,5).All(i=>forced.Stages[i]==0)&&!forced.Conditions.RoleEntryApplied,"forced switch skips wild entry effect");}
  public static void Run(Database db){
   var user=new Fighter(db.pokemon.First(p=>p.name=="선데이"));var target=new Fighter(db.pokemon.First(p=>p.name=="잭 한마"));WildEntryTest(db);var protect=db.moves.First(v=>v.name=="방어");var pivotMove=db.moves.First(v=>v.name=="유턴");var pivotReserve=new Fighter(db.pokemon.First(p=>p.name=="테스트2"));var wait=new Move{name="대기",category="변화",types=new[]{"노말"},accuracy=100,target="자신"};var pivot=Engine.Resolve(db,new[]{user,target},new[]{new BattleCommand{Move=pivotMove,Party=new[]{pivotReserve,user.Copy()}},new BattleCommand{Move=wait}},new Rules(),new[]{new TrainerBattleState(),new TrainerBattleState()},()=>0,x=>x.Candidates.First());Check(pivot.Fighters[0].Data.name==pivotReserve.Data.name&&pivot.Switches.Any(x=>x.Reason==SwitchReason.Pivot&&x.Timing==SwitchTiming.MidTurn),"pivot move switches during the turn: "+string.Join(" / ",pivot.Log));
   var tracker=Tracker(target);Check(SwitchEffectRuntime.HasSwitchRestriction(tracker),"tracker field restriction active");Check(SwitchEffectRuntime.CanSwitch(tracker,SwitchReason.Normal)&&SwitchEffectRuntime.CanSwitch(tracker,SwitchReason.Return)&&SwitchEffectRuntime.CanSwitch(tracker,SwitchReason.Forced),"normal, return and forced switches remain allowed");Check(!SwitchEffectRuntime.CanSwitch(tracker,SwitchReason.Pivot)&&!SwitchEffectRuntime.CanSwitch(tracker,SwitchReason.Potential),"pivot and potential switches are restricted");var blocked=Engine.Resolve(db,new[]{user.Copy(),tracker},new[]{new BattleCommand{Move=pivotMove,Party=new[]{pivotReserve,user.Copy()}},new BattleCommand{Move=wait}},new Rules(),new[]{new TrainerBattleState(),new TrainerBattleState()},()=>0,x=>x.Candidates.First());Check(blocked.Fighters[0].Data.name==user.Data.name&&!blocked.Switches.Any(x=>x.Reason==SwitchReason.Pivot)&&blocked.Log.Any(x=>x.Contains("교대 제한 효과")),"tracker blocks pivot switch");
   var wildBoss=Role(target,"야생의 두목",EffectNormalizer.CanonicalRank("자신의 전능력치",2),TriggerStructures.EntryLabel);var hunter=Role(user,"수렵대원",EffectNormalizer.CanonicalStatIgnore("『야생의 두목』","능력","상승(강화)"),TriggerStructures.FieldLabel);var statRules=new Rules();wildBoss.Stages[1]=2;wildBoss.Stages[2]=2;wildBoss.Stages[5]=2;wildBoss.Multipliers[1]=wildBoss.Multipliers[2]=wildBoss.Multipliers[5]=1.5;var naturalAttack=Engine.Effective(wildBoss,hunter,1,statRules);var naturalDefense=Engine.Effective(wildBoss,hunter,2,statRules);var naturalSpeed=Engine.Effective(wildBoss,hunter,5,statRules);wildBoss.Stages[1]=wildBoss.Stages[2]=wildBoss.Stages[5]=0;wildBoss.Multipliers[1]=wildBoss.Multipliers[2]=wildBoss.Multipliers[5]=1;Check(Engine.Effective(wildBoss,hunter,1,statRules)==naturalAttack&&Engine.Effective(wildBoss,hunter,2,statRules)==naturalDefense&&Engine.Effective(wildBoss,hunter,5,statRules)==naturalSpeed,"hunter ignores wild boss rank and boost on attack, defense and speed");Check(Mechanics.Priority(wildBoss,new Move{name="우선도 검사",category="변화",priority=2},hunter)==2,"stat ignore must not alter move priority");var boostOnly=Role(user,"강화 무시자",EffectNormalizer.CanonicalStatIgnore("상대","공격","강화"),TriggerStructures.FieldLabel);wildBoss.Stages[1]=2;wildBoss.Multipliers[1]=1.5;int boostOnlyValue=Engine.Effective(wildBoss,boostOnly,1,statRules);wildBoss.Multipliers[1]=1;int rankOnlyValue=Engine.Effective(wildBoss,boostOnly,1,statRules);Check(boostOnlyValue==rankOnlyValue&&boostOnlyValue>Engine.Stats(wildBoss,boostOnly.Data.level,statRules)[1],"boost-only ignore preserves rank rise");
   var reaction=new Fighter(new Pokemon{id="reaction",name="피격 교대",level=user.Data.level,@base=(int[])user.Data.@base.Clone(),iv=(int[])user.Data.iv.Clone(),types=(string[])user.Data.types.Clone(),moves=(string[])user.Data.moves.Clone(),potentials=new[]{new Potential{name="피격 교대",description="아군과 교대할 수 있다.",triggers=new[]{TriggerStructures.ReceivedLabel}}}});var reactionReserve=new Fighter(db.pokemon.First(p=>p.name=="테스트2"));var tap=new Move{name="약한공격",category="물리",types=new[]{"노말"},power=1,accuracy=100,priority=7,attack="공격",defense="방어"};var reactionResult=Engine.Resolve(db,new[]{user.Copy(),reaction},new[]{new BattleCommand{Move=tap},new BattleCommand{Move=protect,Party=new[]{reactionReserve,reaction.Copy()}}},new Rules(),new[]{new TrainerBattleState(),new TrainerBattleState()},()=>0,x=>x.Candidates.First());Check(reactionResult.Fighters[1].Data.name==reactionReserve.Data.name&&reactionResult.Switches.Any(x=>x.Reason==SwitchReason.Potential&&x.Timing==SwitchTiming.MidTurn),"mid-turn potential switch");
   var ending=new Fighter(new Pokemon{id="ending",name="턴 종료 교대",level=user.Data.level,@base=(int[])user.Data.@base.Clone(),iv=(int[])user.Data.iv.Clone(),types=(string[])user.Data.types.Clone(),moves=(string[])user.Data.moves.Clone(),potentials=new[]{new Potential{name="턴 종료 교대",description="아군과 교대할 수 있다.",triggers=new[]{TriggerStructures.TurnEndLabel}}}});var endingReserve=new Fighter(db.pokemon.First(p=>p.name=="테스트2"));var endingResult=Engine.Resolve(db,new[]{user.Copy(),ending},new[]{new BattleCommand{Move=protect},new BattleCommand{Move=protect,Party=new[]{endingReserve,ending.Copy()}}},new Rules(),new[]{new TrainerBattleState(),new TrainerBattleState()},()=>0,x=>x.Candidates.First());Check(endingResult.Fighters[1].Data.name==endingReserve.Data.name&&endingResult.Switches.Any(x=>x.Reason==SwitchReason.Potential&&x.Timing==SwitchTiming.TurnEnd),"turn-end potential switch");
  }
 }
}
